    }\n        const baggage = {};\n        let count = 0;\n        let totalSize = 0;\n        if (Array.isArray(headerValue)) {\n            for (let i = 0; i < headerValue.length; i++) {\n                [count, totalSize] = parseBaggageHeaderString(headerValue[i], baggage, count, totalSize);\n            }\n        }\n        else {\n            [count] = parseBaggageHeaderString(headerValue, baggage, count, totalSize);\n        }\n        if (count === 0) {\n            return context;\n        }\n        return propagation.setBaggage(context, propagation.createBaggage(baggage));\n    }\n    fields() {\n        return [BAGGAGE_HEADER];\n    }\n}\n//# sourceMappingURL=W3CBaggagePropagator.js.map","/*\n * Copyright The OpenTelemetry Authors\n * SPDX-License-Identifier: Apache-2.0\n */\nimport { diag } from '@opentelemetry/api';\nexport function sanitizeAttributes(attributes) {\n    const out = {};\n    if (typeof attributes !== 'object' || attributes == null) {\n        return out;\n    }\n    for (const key in attributes) {\n        if (!Object.prototype.hasOwnProperty.call(attributes, key)) {\n            continue;\n        }\n        if (!isAttributeKey(key)) {\n            diag.warn(`Invalid attribute key: ${key}`);\n            continue;\n        }\n        const val = attributes[key];\n        if (!isAttributeValue(val)) {\n            diag.warn(`Invalid attribute value set for key: ${key}`);\n            continue;\n        }\n        if (Array.isArray(val)) {\n            out[key] = val.slice();\n        }\n        else {\n            out[key] = val;\n        }\n    }\n    return out;\n}\nexport function isAttributeKey(key) {\n    return typeof key === 'string' && key !== '';\n}\nexport function isAttributeValue(val) {\n    if (val == null) {\n        return true;\n    }\n    if (Array.isArray(val)) {\n        return isHomogeneousAttributeValueArray(val);\n    }\n    return isValidPrimitiveAttributeValueType(typeof val);\n}\nfunction isHomogeneousAttribute